<template><nav v-if="lastPage>1" class="flex flex-wrap items-center justify-between gap-3 border-t border-adm-line pt-4" aria-label="Pagination"><p class="text-sm text-adm-ink-muted">{{ from }}–{{ to }} of {{ total }}</p><div class="flex gap-2"><button class="min-h-10 rounded-md border border-adm-line px-3 text-sm disabled:opacity-50" :disabled="page<=1" @click="$emit('change',page-1)">Previous</button><span class="flex min-h-10 items-center px-2 text-sm text-adm-ink-muted">Page {{ page }} of {{ lastPage }}</span><button class="min-h-10 rounded-md border border-adm-line px-3 text-sm disabled:opacity-50" :disabled="page>=lastPage" @click="$emit('change',page+1)">Next</button></div></nav></template>
<script setup lang="ts">defineProps<{page:number;lastPage:number;total:number;from?:number;to?:number}>();defineEmits<{change:[page:number]}>()</script>
